function user(id){return db.users.find(u=>u.id===Number(id))}function memo(id){return db.memos.find(m=>m.id===Number(id))}function activeUsers(role,area){return db.users.filter(u=>u.active&&(!role||u.role===role)&&(!area||u.area===area||u.area==='المنطقتين'))}
function audit(m,action,detail=''){db.audit.push({id:Date.now()+Math.random(),memoId:m.id,actor:me.id,action,detail,at:date()});save()}
function notify(uid,title,text,memoId){if(!uid)return;db.notifications.push({id:Date.now()+Math.random(),userId:Number(uid),title,text,memoId,at:iso(),read:false});save();if(me&&me.id===Number(uid))toast(title+': '+text)}
function owner(){return me?.role==='owner'}function qualityManager(){return me?.role==='manager'}function isAssigned(m){if(!me)return false;if(owner()||qualityManager())return true;if(me.role==='inspector')return m.createdBy===me.id;if(me.role==='supervisor')return m.supervisorId===me.id&&m.status==='Pending Supervisor Approval';if(me.role==='quality')return m.qualityId===me.id&&['Pending Quality Approval','Urgent Open'].includes(m.status);if(me.role==='production')return m.productionId===me.id&&['Sent to Production','Rework Required','Urgent Open'].includes(m.status);if(me.role==='observer')return m.observerIds?.includes(me.id);return false}
function visible(){return db.memos.filter(m=>owner()||qualityManager()||isAssigned(m)||m.createdBy===me?.id).sort((a,b)=>b.id-a.id)}
function shell(title,body){$('#app').innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><img src="${LOGO}"><b>NCR-QUALITY<br><small style="font-size:10px;color:#c8d3e5">ACROW · QUALITY MANAGEMENT</small></b></div><div class="top-actions"><span class="user-chip"><b>${esc(me.fullName)}</b><small>${esc(ROLES[me.role])}</small></span><button class="ghost" id="logout">خروج</button></div></header><div class="layout"><aside class="sidebar"><div class="side-title">القائمة الرئيسية</div>${navLink('dashboard','▦','لوحة التحكم')}${navLink('memos','▤','المذكرات')}${['inspector','supervisor'].includes(me.role)?navLink('new','＋','إنشاء مذكرة'):''}${owner()?navLink('users','♙','إدارة المستخدمين')+navLink('workflow','⇄','إدارة مسارات العمل'):''}${qualityManager()?navLink('overview','▤','المتابعة الشاملة'):''}${navLink('notifications','♧','التنبيهات')}${navLink('reports','▥','التقارير')}</aside><main class="content">${title?`<div class="page-head"><div><h1>${title}</h1><div class="sub">ACROW Formwork Technology · نظام إدارة الجودة</div></div></div>`:''}${body}</main></div></div>`;$('#logout').onclick=async()=>{try{await auth.signOut()}catch(e){toast(e.message)}};document.querySelectorAll('[data-route]').forEach(a=>a.onclick=()=>go(a.dataset.route))}
function navLink(r,icon,label){return `<a class="side-link" data-route="${r}"><b>${icon}</b>${label}</a>`}
function go(r){if(r==='memo')return detail();({dashboard,memos,new:newMemo,users,workflow,notifications,reports,overview}[r]||dashboard)()}
