function login(){let has=db.users.some(u=>u.role==='owner');$('#app').innerHTML=`<div class="login-wrap"><section class="login-card"><img class="login-logo" src="${LOGO}"><h1>${has?'تسجيل الدخول للنظام':'إنشاء حساب System Owner'}</h1><p>إدارة الجودة · NCR System</p><form id="loginForm"><div class="field"><label>اسم المستخدم</label><input name="username" required autocomplete="username"></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" required autocomplete="current-password" minlength="6"></div><button>${has?'تسجيل الدخول':'إنشاء حساب المالك'}</button></form><div class="notice" style="margin-top:17px">متصل بـ Firebase Authentication وRealtime Database. كلمة المرور 6 أحرف على الأقل.</div></section></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),u=String(f.get('username')).trim(),p=String(f.get('password'));if(!u||p.length<6)return toast('كلمة المرور يجب ألا تقل عن 6 أحرف');try{localStorage.setItem('ncr_pending_owner_username',u);if(!has){try{await auth.signInWithEmailAndPassword(usernameEmail(u),p);return;}catch(signErr){if(signErr.code!=='auth/user-not-found'&&signErr.code!=='auth/invalid-credential')throw signErr;await auth.createUserWithEmailAndPassword(usernameEmail(u),p);return;}}await auth.signInWithEmailAndPassword(usernameEmail(u),p);}catch(err){console.error(err);toast(err.code==='auth/user-not-found'||err.code==='auth/wrong-password'||err.code==='auth/invalid-credential'?'بيانات الدخول غير صحيحة — تأكد من اسم المستخدم وكلمة المرور المستخدمة أول مرة':err.code==='auth/email-already-in-use'?'الحساب موجود بالفعل. سجّل الدخول بنفس كلمة المرور التي استخدمتها عند إنشائه أول مرة.':err.message);}}}

function dashboard(){let a=visible(),open=a.filter(m=>m.status!=='Closed').length,urgent=a.filter(m=>m.type==='urgent'&&m.status!=='Closed').length,closed=a.length-open,late=a.filter(isLate).length,closure=a.length?closed/a.length*100:0;let cards=[['إجمالي المذكرات',a.length,'كل السجلات'],['مذكرات مفتوحة',open,'تحت الإجراء'],['مذكرات عاجلة',urgent,'إيقاف خط الإنتاج'],['مذكرات متأخرة',late,'تجاوزت 24 ساعة']];let states=['Pending Supervisor Approval','Pending Quality Approval','Sent to Production','Urgent Open','Rework Required','Responded','Closed'];let body=`<div class="grid">${cards.map(c=>`<div class="metric"><span>${c[0]}</span><strong>${c[1]}</strong><small>${c[2]}</small></div>`).join('')}</div><div class="analytics-grid"><section class="card analytics-card"><h2>مؤشر الأداء العام</h2><div class="donut-wrap"><div class="donut" style="--value:${closure}%"><div><strong>${closure.toFixed(1)}%</strong><small>نسبة الإغلاق</small></div></div><div class="legend"><span><i class="legend-dot closed-dot"></i>مغلقة: ${closed}</span><span><i class="legend-dot open-dot"></i>مفتوحة: ${open}</span><span><i class="legend-dot late-dot"></i>متأخرة: ${late}</span></div></div></section><section class="card analytics-card"><h2>توزيع المذكرات حسب الحالة</h2>${states.map(st=>{let n=a.filter(m=>m.status===st).length,pct=a.length?n/a.length*100:0;return `<div class="chart-row"><div><span>${statusAr(st)}</span><b>${n} <small>${pct.toFixed(0)}%</small></b></div><div class="chart-track"><i style="width:${pct}%"></i></div></div>`}).join('')}</section></div><div class="split"><section class="card"><h2>المذكرات حسب المنطقة</h2>${AREAS.map(ar=>{let n=a.filter(m=>m.area===ar).length,pct=a.length?n/a.length*100:0;return `<div class="bar-row"><span>${esc(ar)}</span><div class="bar"><i style="width:${pct}%"></i></div><b>${n}</b></div>`}).join('')}<p class="sub">مؤشرات مباشرة من بيانات النظام</p></section><section class="card"><h2>معدل الإغلاق حسب المنطقة</h2>${AREAS.map(ar=>{let rows=a.filter(m=>m.area===ar),n=rows.length?rows.filter(m=>m.status==='Closed').length/rows.length*100:0;return `<div class="chart-row"><div><span>${esc(ar)}</span><b>${n.toFixed(1)}%</b></div><div class="chart-track"><i class="green-fill" style="width:${n}%"></i></div></div>`}).join('')}</section></div><section class="card"><h2>أحدث المذكرات</h2>${memoTable(a.slice(0,8))}</section>`;shell('لوحة التحكم',body)}
function statusAr(s){return ({'Pending Supervisor Approval':'بانتظار مشرف الجودة','Pending Quality Approval':'بانتظار مهندس الجودة','Sent to Production':'لدى مهندس الإنتاج','Urgent Open':'عاجل · إيقاف إنتاج','Rework Required':'إعادة تصحيح','Responded':'بانتظار فحص المفتش','Closed':'مغلقة'})[s]||s}
function isLate(m){return m.status!=='Closed'&&Date.now()-new Date(m.lastActionAt||m.createdISO).getTime()>86400000}
function memoTable(a){if(!a.length)return '<div class="empty">لا توجد مذكرات حتى الآن.</div>';return `<div class="table-wrap"><table><tr><th>رقم المذكرة</th><th>النوع</th><th>المنطقة</th><th>المنتج / أمر التشغيل</th><th>الحالة</th><th>آخر تحديث</th><th></th></tr>${a.map(m=>`<tr><td><b>${m.no}</b></td><td>${m.type==='urgent'?'<span class="pill urgent">STOP PRODUCTION</span>':'عادية'}</td><td>${esc(m.area)}</td><td>${esc(m.product||'—')}</td><td><span class="pill ${m.status==='Closed'?'closed':isLate(m)?'urgent':'pending'}">${statusAr(m.status)}</span></td><td>${esc(m.lastAction||m.createdAt)}</td><td><button class="ghost" data-open="${m.id}">فتح</button></td></tr>`).join('')}</table></div>`}
function memos(){shell('المذكرات',`<section class="card">${memoTable(visible())}</section>`);bindOpen()}
function bindOpen(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selectedMemo=Number(b.dataset.open);detail()})}
function newMemo(){if(!['inspector','supervisor'].includes(me.role))return forbidden();let body=`<section class="card"><form id="memoForm"><h2>نوع المذكرة</h2><div class="form-grid"><label class="memo-type"><input type="radio" name="type" value="normal" checked><span><b>مذكرة جودة عادية</b><br><small>تمر بمسار الاعتماد الطبيعي</small></span></label><label class="memo-type"><input type="radio" name="type" value="urgent"><span><b style="color:#b42332">🚨 عاجل · إيقاف خط الإنتاج</b><br><small>إخطار مباشر لمهندس الجودة والإنتاج</small></span></label></div><div class="form-grid" style="margin-top:18px"><div class="field"><label>المنطقة / المصنع</label><select name="area" required>${AREAS.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>اسم المنتج</label><input name="product" required></div><div class="field"><label>رقم أمر التشغيل / الشغل</label><input name="workOrder" required></div><div class="field"><label>نوع العيب</label><input name="defect" required></div><div class="field"><label>مكان العيب</label><input name="location"></div><div class="field"><label>درجة الخطورة</label><select name="severity"><option>منخفض</option><option selected>متوسط</option><option>مرتفع</option><option>حرج</option></select></div><div class="field full"><label>وصف العيب بالتفصيل</label><textarea name="description" required></textarea></div><div class="field full"><label>صورة العيب (اختياري)</label><input name="defectImage" type="file" accept="image/*" capture="environment"></div></div><div id="routePreview" class="notice" style="margin-top:16px"></div><div class="actions"><button>حفظ وإرسال المذكرة</button></div></form></section>`;shell('إنشاء مذكرة جودة',body);let form=$('#memoForm'),update=()=>{let area=form.area.value,w=db.workflow[area]||{},s=user(w.supervisorId),q=user(w.qualityId),p=user(w.productionId);$('#routePreview').innerHTML=`<b>مسار التوجيه حسب إعدادات System Owner:</b><br>مشرف الجودة: ${esc(s?.fullName||'غير محدد')} · مهندس الجودة: ${esc(q?.fullName||'غير محدد')} · مهندس الإنتاج: ${esc(p?.fullName||'غير محدد')}`};form.area.onchange=update;update();form.onsubmit=async e=>{e.preventDefault();let f=new FormData(form),area=f.get('area'),w=db.workflow[area]||{},s=user(w.supervisorId),q=user(w.qualityId),p=user(w.productionId),type=f.get('type');if(!s||!q||!p||![s,q,p].every(x=>x.active))return toast('مسار الاعتماد غير مكتمل. راجع إعدادات Workflow Management.');let file=form.defectImage.files[0],image=file?await readFile(file):null,n=db.nextMemo++,m={id:n,no:'ACRO-'+String(n).padStart(5,'0'),type,area,product:f.get('product').trim(),workOrder:f.get('workOrder').trim(),defect:f.get('defect').trim(),location:f.get('location').trim(),severity:f.get('severity'),description:f.get('description').trim(),createdBy:me.id,createdAt:date(),createdISO:iso(),lastAction:date(),lastActionAt:iso(),supervisorId:s.id,qualityId:q.id,productionId:p.id,observerIds:activeUsers('observer',area).map(u=>u.id),defectImage:image,status:type==='urgent'?'Urgent Open':(me.role==='supervisor'?'Pending Quality Approval':'Pending Supervisor Approval'),createdByRole:me.role,events:[]};db.memos.push(m);audit(m,'تم إنشاء المذكرة',type==='urgent'?'عاجلة وإيقاف خط الإنتاج':(me.role==='supervisor'?'إنشاء المشرف · إرسال مباشر لمهندس الجودة':'إنشاء المفتش · إرسال إلى مشرف الجودة'));if(type==='urgent'){notify(q.id,'مذكرة عاجلة',m.no+' · إيقاف خط الإنتاج',m.id);notify(p.id,'مذكرة عاجلة',m.no+' · إيقاف خط الإنتاج',m.id)}else if(me.role==='supervisor'){notify(q.id,'مذكرة جديدة من مشرف الجودة',m.no+' · بانتظار اعتمادك',m.id)}else notify(s.id,'مذكرة جديدة',m.no+' · بانتظار اعتمادك',m.id);m.observerIds.forEach(id=>notify(id,'للعلم فقط','تم إنشاء مذكرة '+m.no,m.id));save();selectedMemo=m.id;toast('تم إرسال المذكرة بنجاح');detail()}}
function readFile(file){return new Promise((resolve,reject)=>{if(file.size>4*1024*1024)return reject(toast('الصورة أكبر من 4MB'));let r=new FileReader();r.onload=()=>resolve({name:file.name,data:r.result});r.onerror=reject;r.readAsDataURL(file)})}
function detail(){let m=memo(selectedMemo);if(!m)return memos();let creatorRole=m.createdByRole||user(m.createdBy)?.role||'inspector',creatorLabel=creatorRole==='supervisor'?'إنشاء مشرف الجودة':'إنشاء مفتش الجودة';let steps=m.type==='urgent'?[creatorLabel,'إخطار مهندس الجودة والإنتاج','رد مهندس الإنتاج','فحص منشئ المذكرة والإغلاق']:creatorRole==='supervisor'?[creatorLabel,'اعتماد مهندس الجودة','رد مهندس الإنتاج','فحص منشئ المذكرة والإغلاق']:[creatorLabel,'اعتماد مشرف الجودة','اعتماد مهندس الجودة','رد مهندس الإنتاج','فحص منشئ المذكرة والإغلاق'];let body=`${m.type==='urgent'?'<div class="urgent-banner">🚨 STOP PRODUCTION · مذكرة عاجلة تتطلب تدخلًا فوريًا</div>':''}<section class="card"><div class="page-head"><div><h2>${m.no}</h2><span class="pill ${m.status==='Closed'?'closed':'pending'}">${statusAr(m.status)}</span></div><span class="pill">${m.area}</span></div><div class="stepper">${steps.map((x,i)=>`<span class="step ${i<stepIndex(m)?'done':i===stepIndex(m)?'current':''}">${i+1} · ${x}</span>`).join('')}</div><div class="form-grid"><div><b>${creatorRole==='supervisor'?'مشرف الجودة':'مفتش الجودة'}:</b> ${esc(user(m.createdBy)?.fullName)}</div><div><b>المنطقة:</b> ${esc(m.area)}</div><div><b>المنتج:</b> ${esc(m.product)}</div><div><b>أمر التشغيل:</b> ${esc(m.workOrder)}</div><div><b>نوع العيب:</b> ${esc(m.defect)}</div><div><b>الموقع:</b> ${esc(m.location||'—')}</div><div><b>الخطورة:</b> ${esc(m.severity)}</div><div><b>تاريخ الإنشاء:</b> ${esc(m.createdAt)}</div></div><h3>وصف العيب</h3><p>${esc(m.description)}</p>${m.defectImage?`<img class="file-preview" src="${m.defectImage.data}" alt="صورة العيب">`:''}</section>${actionsFor(m)}<section class="card"><h2>سجل المذكرة والإجراءات</h2>${(db.audit.filter(x=>x.memoId===m.id).slice().reverse().map(x=>`<p><b>${esc(x.action)}</b> · ${esc(user(x.actor)?.fullName||'—')} · ${esc(x.at)}<br><small>${esc(x.detail)}</small></p>`).join(''))||'<p class="empty">لا توجد تحديثات.</p>'}</section>`;shell('تفاصيل المذكرة',body);bindActions(m)}
function stepIndex(m){let creatorRole=m.createdByRole||user(m.createdBy)?.role||'inspector';if(m.type==='urgent')return m.status==='Urgent Open'?1:['Sent to Production','Rework Required'].includes(m.status)?2:m.status==='Responded'?3:4;if(creatorRole==='supervisor')return m.status==='Pending Quality Approval'?1:['Sent to Production','Rework Required'].includes(m.status)?2:m.status==='Responded'?3:4;return m.status==='Pending Supervisor Approval'?1:m.status==='Pending Quality Approval'?2:['Sent to Production','Rework Required'].includes(m.status)?3:m.status==='Responded'?4:5}
function actionsFor(m){if(m.status==='Closed')return '<section class="card"><h2>تم إغلاق المذكرة</h2><span class="pill closed">CLOSED</span></section>';let h='';if(me.role==='supervisor'&&m.type==='normal'&&m.status==='Pending Supervisor Approval'&&me.id===m.supervisorId)h=`<section class="card"><h2>اعتماد مشرف الجودة</h2><p>مراجعة تفاصيل المذكرة ثم اعتمادها لإرسالها لمهندس الجودة.</p><button class="green" data-action="superapprove">✓ APPROVE</button></section>`;if(me.role==='quality'&&m.type==='normal'&&m.status==='Pending Quality Approval'&&me.id===m.qualityId)h+=`<section class="card"><h2>مراجعة مهندس الجودة</h2><div class="field"><label>ملاحظة لمهندس الإنتاج (اختياري)</label><textarea id="qualityNote" placeholder="اكتب ملاحظة أو توجيهًا لمهندس الإنتاج..."></textarea></div><button class="green" data-action="qualityapprove">✓ APPROVE & SEND</button></section>`;if(me.role==='production'&&me.id===m.productionId&&['Sent to Production','Rework Required','Urgent Open'].includes(m.status))h+=`<section class="card"><h2>الإجراء التصحيحي · مهندس الإنتاج</h2>${m.qualityNote?`<div class="notice">ملاحظة مهندس الجودة: ${esc(m.qualityNote)}</div>`:''}<div class="field"><label>تفاصيل التصحيح المنفذ</label><textarea id="productionReply" placeholder="اشرح الإجراء التصحيحي..." required></textarea></div><div class="field" style="margin-top:12px"><label>صورة الإصلاح (اختياري)</label><input id="repairImage" type="file" accept="image/*" capture="environment"></div><button data-action="reply">إرسال للمفتش</button></section>`;if(me.id===m.createdBy&&['inspector','supervisor'].includes(me.role)&&m.status==='Responded')h+=`<section class="card"><h2>مراجعة الإصلاح · قرار منشئ المذكرة</h2><p>${esc(m.productionReply||'')}</p>${m.repairImage?`<img class="file-preview" src="${m.repairImage.data}" alt="صورة الإصلاح">`:''}<div class="field"><label>ملاحظات الفحص (اختياري)</label><textarea id="inspectionNote" placeholder="ملاحظاتك على الإصلاح..."></textarea></div><div class="actions"><button class="green" data-action="close">✓ ACCEPT & CLOSE</button><button class="red" data-action="rework">✕ REJECT & REWORK</button></div></section>`;if(owner()&&m.status!=='Closed')h+=`<section class="card"><h2>عرض إداري</h2><p class="sub">المالك لديه صلاحية المتابعة والإدارة. الاعتمادات التشغيلية تنفذ من حسابات أصحاب الخطوات.</p></section>`;return h}
function bindActions(m){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{let act=b.dataset.action;if(act==='superapprove'&&me.id===m.supervisorId&&m.status==='Pending Supervisor Approval'){m.status='Pending Quality Approval';audit(m,'اعتماد مشرف الجودة');touch(m);notify(m.qualityId,'مذكرة بانتظار اعتمادك',m.no,m.id)}else if(act==='qualityapprove'&&me.id===m.qualityId&&['Pending Quality Approval','Urgent Open'].includes(m.status)){m.qualityNote=$('#qualityNote').value.trim();m.status='Sent to Production';audit(m,'اعتماد مهندس الجودة',m.qualityNote);touch(m);notify(m.productionId,'مذكرة بانتظار الإجراء التصحيحي',m.no,m.id)}else if(act==='reply'&&me.id===m.productionId){let text=$('#productionReply').value.trim();if(!text)return toast('اكتب الإجراء التصحيحي أولًا');let file=$('#repairImage').files[0],img=file?await readFile(file):null;m.productionReply=text;m.repairImage=img;m.status='Responded';audit(m,'رد مهندس الإنتاج',text);touch(m);notify(m.createdBy,'رد مهندس الإنتاج جاهز للفحص',m.no,m.id)}else if(act==='close'&&me.id===m.createdBy&&m.status==='Responded'){m.inspectionNote=$('#inspectionNote').value.trim();m.status='Closed';m.closedAt=date();audit(m,'قبول الإصلاح وإغلاق المذكرة',m.inspectionNote);touch(m);toast('تم إغلاق المذكرة بنجاح')}else if(act==='rework'&&me.id===m.createdBy&&m.status==='Responded'){m.inspectionNote=$('#inspectionNote').value.trim();m.status='Rework Required';audit(m,'رفض الإصلاح وإعادة المعالجة',m.inspectionNote);touch(m);notify(m.productionId,'تم رفض الإصلاح وإرجاع المذكرة',m.no,m.id);toast('تم إرجاع المذكرة لمهندس الإنتاج')}else return;save();detail()})}
function touch(m){m.lastAction=date();m.lastActionAt=iso()}
function users(){if(!owner())return forbidden();let body=`<section class="card"><h2>إنشاء حساب جديد</h2><form id="userForm"><div class="form-grid"><div class="field"><label>الاسم الكامل</label><input name="fullName" required></div><div class="field"><label>اسم المستخدم</label><input name="username" required></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" required></div><div class="field"><label>نوع الحساب / الصلاحية</label><select name="role">${Object.entries(ROLES).filter(([k])=>k!=='owner').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="field"><label>المنطقة</label><select name="area">${AREAS.map(a=>`<option>${esc(a)}</option>`).join('')}<option>المنطقتين</option></select></div></div><p class="sub">يمكنك إنشاء حسابك الشخصي كمفتش جودة من هنا، مع الاحتفاظ بحساب System Owner منفصل. كلمة المرور يجب ألا تقل عن 6 أحرف، وتُدار عبر Firebase Authentication.</p><button>إنشاء الحساب</button></form></section><section class="card"><h2>إضافة منطقة جديدة</h2><form id="areaForm" class="form-grid"><div class="field"><label>اسم المنطقة / المصنع</label><input name="areaName" required placeholder="مثال: مصنع 4"></div><div class="field" style="align-self:end"><button class="green">＋ إضافة المنطقة</button></div></form><p class="sub">ستظهر المنطقة الجديدة تلقائيًا في إنشاء الحسابات والمذكرات وإدارة مسارات العمل والتقارير.</p></section><section class="card"><h2>الحسابات الحالية</h2><div class="notice" style="margin-bottom:12px">إدارة الحسابات والصلاحيات متاحة من هنا. لا يتم عرض كلمات المرور.</div><div class="table-wrap"><table><tr><th>الاسم</th><th>Username</th><th>الدور</th><th>المنطقة</th><th>الحالة</th><th>كلمة المرور</th><th></th></tr>${db.users.map(u=>`<tr><td>${esc(u.fullName)}</td><td>${esc(u.username)}</td><td>${ROLES[u.role]}</td><td>${esc(u.area||'—')}</td><td>${u.active?'نشط':'موقوف'}</td><td><span class="password-value" id="password-${u.id}" hidden></span><button type="button" class="ghost" data-reveal="${u.id}">إظهار</button></td><td>${u.id===me.id?'الحساب الحالي':`<button class="ghost" data-toggle="${u.id}">${u.active?'إيقاف':'تفعيل'}</button>`}</td></tr>`).join('')}</table></div></section>`;shell('إدارة المستخدمين والصلاحيات',body);$('#userForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),username=f.get('username').trim(),password=String(f.get('password')),role=f.get('role');if(db.users.some(u=>u.username.toLowerCase()===username.toLowerCase()))return toast('اسم المستخدم مستخدم بالفعل');if(password.length<6)return toast('كلمة المرور يجب ألا تقل عن 6 أحرف');try{secondaryApp=firebase.apps.find(a=>a.name==='NCR_ACCOUNT_CREATOR')||firebase.initializeApp(firebaseConfig,'NCR_ACCOUNT_CREATOR');let secondary=secondaryApp.auth();let cred=await secondary.createUserWithEmailAndPassword(usernameEmail(username),password);db.users.push({id:db.nextUser++,authUid:cred.user.uid,fullName:f.get('fullName').trim(),username,role,area:f.get('area'),active:true});await dataRef.set(db);await secondary.signOut();toast('تم إنشاء الحساب بنجاح');users()}catch(err){console.error(err);toast(err.code==='auth/email-already-in-use'?'اسم المستخدم مستخدم بالفعل':err.message)}};$('#areaForm').onsubmit=e=>{e.preventDefault();let name=new FormData(e.target).get('areaName').trim();if(!name)return;if(AREAS.some(a=>a.toLowerCase()===name.toLowerCase()))return toast('هذه المنطقة موجودة بالفعل');AREAS.push(name);db.areas=AREAS;save();toast('تمت إضافة المنطقة بنجاح');users()};document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{let u=user(b.dataset.toggle);u.active=!u.active;save();users()});document.querySelectorAll('[data-reveal]').forEach(b=>b.onclick=()=>{let id=Number(b.dataset.reveal),u=user(id),el=$('#password-'+id),show=!el.hidden;document.querySelectorAll('.password-value').forEach(x=>{x.hidden=true;x.textContent=''});document.querySelectorAll('[data-reveal]').forEach(x=>x.textContent='إظهار');if(!show){el.textContent=u.password;el.hidden=false;b.textContent='إخفاء'}else{el.hidden=true;el.textContent='';b.textContent='إظهار'}})}
function workflow(){if(!owner())return forbidden();let body=AREAS.map(area=>{let w=db.workflow[area]||{};return `<section class="card"><h2>${area}</h2><form class="workflowForm" data-area="${area}"><div class="form-grid">${[['supervisorId','مشرف الجودة','supervisor'],['qualityId','مهندس الجودة','quality'],['productionId','مهندس الإنتاج','production']].map(([key,label,role])=>`<div class="field"><label>${label}</label><select name="${key}"><option value="">— اختر المسؤول —</option>${activeUsers(role,area).map(u=>`<option value="${u.id}" ${Number(w[key])===u.id?'selected':''}>${esc(u.fullName)} · ${esc(u.username)}</option>`).join('')}</select></div>`).join('')}</div><button style="margin-top:14px">حفظ مسار المنطقة</button></form></section>`}).join('');shell('إدارة مسارات العمل · Workflow Management',`<div class="notice" style="margin-bottom:16px">أنت كـ System Owner تختار المسؤولين لكل منطقة. تغيير المسار يؤثر على المذكرات الجديدة فقط؛ المذكرات القائمة تحتفظ بمسارها الأصلي.</div>${body}`);document.querySelectorAll('.workflowForm').forEach(form=>form.onsubmit=e=>{e.preventDefault();let f=new FormData(form),a=form.dataset.area;if(!f.get('supervisorId')||!f.get('qualityId')||!f.get('productionId'))return toast('يجب تحديد المسؤولين الثلاثة');db.workflow[a]={supervisorId:Number(f.get('supervisorId')),qualityId:Number(f.get('qualityId')),productionId:Number(f.get('productionId'))};save();toast('تم حفظ مسار '+a)})}
function notifications(){let a=db.notifications.filter(n=>n.userId===me.id).sort((x,y)=>y.id-x.id);shell('التنبيهات',`<section class="card">${a.length?a.map(n=>`<div style="padding:13px 0;border-bottom:1px solid var(--line)"><b>${esc(n.title)}</b><p>${esc(n.text)}</p><small class="sub">${new Date(n.at).toLocaleString('ar-EG')}</small>${n.memoId?` <button class="ghost" data-open="${n.memoId}">فتح المذكرة</button>`:''}</div>`).join(''):'<div class="empty">لا توجد تنبيهات.</div>'}</section>`);a.forEach(n=>n.read=true);save();bindOpen()}
function overview(){if(!qualityManager())return forbidden();let staff=db.users.filter(u=>u.role!=='owner'),memos=visible(),byArea=AREAS.map(area=>({area,users:staff.filter(u=>u.area===area||u.area==='المنطقتين'),memos:memos.filter(m=>m.area===area)}));let body=`<section class="card"><h2>نظرة عامة على الأقسام</h2><div class="grid">${[['إجمالي الموظفين',staff.length],['مفتشو الجودة',staff.filter(u=>u.role==='inspector').length],['مهندسو الجودة',staff.filter(u=>u.role==='quality').length],['مهندسو الإنتاج',staff.filter(u=>u.role==='production').length]].map(x=>`<div class="metric"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></section>${byArea.map(x=>`<section class="card"><h2>${esc(x.area)}</h2><p class="sub">عدد المذكرات: ${x.memos.length} · المفتوحة: ${x.memos.filter(m=>m.status!=='Closed').length} · المغلقة: ${x.memos.filter(m=>m.status==='Closed').length}</p><div class="table-wrap"><table><tr><th>اسم الموظف</th><th>اسم المستخدم</th><th>الوظيفة</th><th>الحالة</th></tr>${x.users.map(u=>`<tr><td>${esc(u.fullName)}</td><td>${esc(u.username)}</td><td>${esc(ROLES[u.role])}</td><td>${u.active?'نشط':'موقوف'}</td></tr>`).join('')||'<tr><td colspan="4">لا يوجد موظفون مسجلون في هذا القسم.</td></tr>'}</table></div><h3>آخر مذكرات القسم</h3>${memoTable(x.memos.slice(0,6))}</section>`).join('')}<section class="card"><h2>سجل متابعة الجودة</h2><div class="table-wrap"><table><tr><th>التاريخ</th><th>المذكرة</th><th>صاحب الإجراء</th><th>الإجراء</th><th>التفاصيل</th></tr>${db.audit.slice().reverse().slice(0,60).map(ev=>{let m=memo(ev.memoId);return `<tr><td>${esc(ev.at)}</td><td>${esc(m?.no||'—')}</td><td>${esc(user(ev.actor)?.fullName||'—')}</td><td>${esc(ev.action)}</td><td>${esc(ev.detail||'—')}</td></tr>`}).join('')||'<tr><td colspan="5">لا توجد سجلات.</td></tr>'}</table></div></section>`;shell('المتابعة الشاملة · مدير الجودة',body);bindOpen()}

function reports(){let a=visible(),areas=AREAS.map(ar=>({ar,total:a.filter(m=>m.area===ar).length,closed:a.filter(m=>m.area===ar&&m.status==='Closed').length,urgent:a.filter(m=>m.area===ar&&m.type==='urgent').length}));shell('التقارير والإحصائيات',`<section class="card"><h2>ملخص المناطق</h2><div class="table-wrap"><table><tr><th>المنطقة</th><th>الإجمالي</th><th>مغلقة</th><th>عاجلة</th><th>نسبة الإغلاق</th></tr>${areas.map(x=>`<tr><td>${x.ar}</td><td>${x.total}</td><td>${x.closed}</td><td>${x.urgent}</td><td>${x.total?(x.closed/x.total*100).toFixed(1):0}%</td></tr>`).join('')}</table></div></section>` )}
function checkOverdue(){if(!me)return;let t=Date.now();db.memos.filter(m=>m.status!=='Closed'&&t-new Date(m.lastActionAt||m.createdISO).getTime()>=86400000).forEach(m=>{let recipients=m.status==='Pending Supervisor Approval'?[m.supervisorId]:m.status==='Pending Quality Approval'?[m.qualityId]:m.status==='Responded'?[m.createdBy]:m.status==='Urgent Open'?[m.qualityId,m.productionId]:[m.productionId];recipients.forEach(recipient=>{let exists=db.notifications.some(n=>n.memoId===m.id&&n.title==='تنبيه تأخير 24 ساعة'&&n.userId===recipient&&Date.now()-new Date(n.at).getTime()<86400000);if(!exists)notify(recipient,'تنبيه تأخير 24 ساعة','المذكرة '+m.no+' لم يتم الرد عليها خلال 24 ساعة.',m.id)})})}
function forbidden(){shell('غير مصرح',`<section class="card"><h2>403 · ليس لديك صلاحية لهذه الصفحة</h2></section>`)}
setInterval(()=>{if(me)checkOverdue()},60000);init();
